namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 4;
    private readonly Lock _lock = new();
    private readonly List<Notification> _notifications =
    [
        new(1, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-30)),
        new(2, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-15)),
        new(3, "New feature: dark mode is available.", DateTime.UtcNow.AddMinutes(-5)),
    ];

    private static readonly string[] SampleMessages =
    [
        "You have a new follower.",
        "Your report is ready to download.",
        "Scheduled maintenance tonight at 11 PM.",
        "Someone commented on your post.",
        "Your subscription renews tomorrow.",
        "A new version of the app is available.",
        "Disk usage exceeded 80%.",
        "Backup completed successfully.",
    ];

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.OrderByDescending(n => n.Timestamp).ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(DateTime since)
    {
        // Randomly generate 0-1 new notifications per poll
        lock (_lock)
        {
            if (Random.Shared.Next(3) == 0) // ~33% chance each poll
            {
                var msg = SampleMessages[Random.Shared.Next(SampleMessages.Length)];
                _notifications.Add(new(_nextId++, msg, DateTime.UtcNow));
            }

            return Task.FromResult(
                _notifications
                    .Where(n => n.Timestamp > since)
                    .OrderByDescending(n => n.Timestamp)
                    .ToList());
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationService
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
</h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications.</em></p>
}
else
{
    <ul class="list-group mt-3">
        @foreach (var n in notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<Notification>? Notifications { get; set; }

    private List<Notification> notifications = [];
    private CancellationTokenSource? _cts;
    private DateTime _latestTimestamp;

    protected override async Task OnInitializedAsync()
    {
        Notifications ??= await NotificationService.GetNotificationsAsync();
        notifications = Notifications;
        _latestTimestamp = notifications.Count > 0
            ? notifications.Max(n => n.Timestamp)
            : DateTime.UtcNow;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var newer = await NotificationService.GetNotificationsSinceAsync(_latestTimestamp);
            if (newer.Count > 0)
            {
                notifications.InsertRange(0, newer);
                _latestTimestamp = newer.Max(n => n.Timestamp);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

